import{_ as e,o as t,c as r,a6 as n}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"HuggingFace 模型下载与部署","description":"从 Hub 上把模型拉下来、在自己的机器上跑起来，再用它的数据集与算力训出自己的模型——一份偏实操的 HuggingFace 生态指南。","frontmatter":{"title":"HuggingFace 模型下载与部署","description":"从 Hub 上把模型拉下来、在自己的机器上跑起来，再用它的数据集与算力训出自己的模型——一份偏实操的 HuggingFace 生态指南。","source":"https://daiw.org/manual/huggingface"},"headers":[],"relativePath":"manual/llm/huggingface/index.md","filePath":"manual/llm/huggingface/index.md"}'),o={name:"manual/llm/huggingface/index.md"};function g(l,a,i,s,c,u){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="huggingface-模型下载与部署" tabindex="-1">HuggingFace 模型下载与部署 <a class="header-anchor" href="#huggingface-模型下载与部署" aria-label="Permalink to &quot;HuggingFace 模型下载与部署&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/huggingface" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David（道雾轩） · 原文更新于 2026-11-06</p></blockquote><blockquote><p>从 Hub 上把模型拉下来、在自己的机器上跑起来，再用它的数据集与算力训出自己的模型——一份偏实操的 HuggingFace 生态指南。</p></blockquote><h2 id="序-·-把-别人的模型-变成-你机器上跑着的东西" tabindex="-1">序 · 把“别人的模型”变成“你机器上跑着的东西” <a class="header-anchor" href="#序-·-把-别人的模型-变成-你机器上跑着的东西" aria-label="Permalink to &quot;序 · 把“别人的模型”变成“你机器上跑着的东西”&quot;">​</a></h2><p>HuggingFace 上有上百万个模型。但从“看到一个模型页”到“它在我的机器上真的跑起来了”，中间隔着一串具体问题：</p><ul><li>这个仓库里十几个文件，我该下哪些？下错了白等半小时。</li><li>我的显卡 8 GB，到底能跑多大的模型？跑不动的话有别的办法吗？</li><li>国内下载动辄断流，怎么才能稳定拉下来？</li><li>想微调一个自己的模型，数据从哪来、要多少显存、单卡够不够？</li><li>每月 9 美元的 PRO 到底买到了什么？什么时候值得掏这个钱？</li></ul><p>这个专栏就是逐个回答这些问题。<strong>它不讲 Transformer 原理</strong>（那是<a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">《AI 大模型解构》</a>与<a href="https://daiw.org/manual/bit-to-agi" target="_blank" rel="noreferrer">《从 Bit 到 AGI》</a>的事），只讲<strong>手上的操作</strong>：怎么下、怎么跑、怎么训、怎么省钱。</p><h2 id="这个专栏假设你" tabindex="-1">这个专栏假设你 <a class="header-anchor" href="#这个专栏假设你" aria-label="Permalink to &quot;这个专栏假设你&quot;">​</a></h2><ul><li>会用命令行，装过 Python 包。</li><li>有一台能跑起来的机器——<strong>哪怕只有 CPU 也行</strong>，第 3 部分有纯 CPU 的路线。</li><li>想动手，而不只是想了解。</li></ul><p>不需要你懂深度学习理论。需要显存的地方我会给出具体数字，跑不动的地方会给替代方案。</p><h2 id="六个部分" tabindex="-1">六个部分 <a class="header-anchor" href="#六个部分" aria-label="Permalink to &quot;六个部分&quot;">​</a></h2><p><strong>第 1 部分 · 认识 Hub</strong> —— 先看清你面对的是什么。</p><p>HuggingFace 是三样东西叠在一起：一个托管平台（Hub）、一堆 Python 库（transformers / datasets / peft…）、一组付费服务。一个模型仓库里的每个文件是干什么的、<code>safetensors</code> 和 <code>.bin</code> 差在哪、GGUF 又是什么——搞清这些，后面才不会盲下。</p><p><strong>第 2 部分 · 下载</strong> —— 稳、快、只下需要的。</p><p><code>hf</code> 命令行、token 权限、缓存目录在哪、断点续传、怎么只下一个量化版本而不是整个仓库。以及<strong>国内访问</strong>这个绕不开的话题——镜像站怎么配、离线环境怎么办。</p><p><strong>第 3 部分 · 单机部署</strong> —— 让它真的跑起来。</p><p>先按<strong>显存档位</strong>给一张对照表（4 G 到 48 G 各能跑什么），再讲四条部署路线：<code>transformers</code> 直接跑、GGUF + llama.cpp / Ollama（<strong>CPU 也能跑</strong>）、vLLM（要吞吐时）。最后是一份<strong>经典模型清单</strong>，每个都给可以直接粘贴运行的命令。</p><p><strong>第 4 部分 · 数据集</strong> —— Hub 上不只有模型。</p><p><code>datasets</code> 库怎么用、几十 GB 的数据集怎么流式读而不撑爆硬盘、怎么把自己的数据整理成标准格式传上去。</p><p><strong>第 5 部分 · 自己训模型</strong> —— 单卡也能做的事。</p><p><strong>LoRA / QLoRA 微调</strong>是普通人最现实的路径：一张 16 G 的卡就能微调 7B 模型。这部分讲怎么配、怎么算显存、OOM 了怎么办、训完怎么评估、怎么推回 Hub。</p><p><strong>第 6 部分 · 算力与收费</strong> —— 钱花在刀刃上。</p><p>本地、Colab、Spaces、Inference Endpoints 各自的成本与适用场景；PRO 订阅、ZeroGPU、按小时计费的 Space GPU 分别买到了什么；以及几条实测有效的省钱策略。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>关于价格与 API 的时效性</strong>：HuggingFace 的定价与 CLI 命名变过几次（<code>huggingface-cli</code> 现在叫 <code>hf</code>）。本专栏写作时以当前版本为准，凡涉及具体价格的地方我都会标明“以官网为准”——<strong>掏钱之前请去 <a href="https://huggingface.co/pricing" target="_blank" rel="noreferrer">huggingface.co/pricing</a> 核一遍</strong>。</p><p>技术操作部分（下载、部署、微调）的稳定性要高得多，基本不会因为版本小改而失效。</p></div><h2 id="一条最短路径" tabindex="-1">一条最短路径 <a class="header-anchor" href="#一条最短路径" aria-label="Permalink to &quot;一条最短路径&quot;">​</a></h2><p>如果你现在就想试点什么，不必按顺序读。三条常见目标各自的最短路线：</p><table tabindex="0"><thead><tr><th>你想</th><th>直接读</th></tr></thead><tbody><tr><td>在自己电脑上跑个大模型聊天</td><td><a href="/Front2Full/manual/llm/huggingface/choose-by-vram">按显存选模型</a> → <a href="/Front2Full/manual/llm/huggingface/gguf-llamacpp-ollama">GGUF 路线</a></td></tr><tr><td>把某个模型接进自己的程序</td><td><a href="/Front2Full/manual/llm/huggingface/downloading">下载</a> → <a href="/Front2Full/manual/llm/huggingface/transformers-serving">transformers 部署</a></td></tr><tr><td>微调一个属于自己的模型</td><td><a href="/Front2Full/manual/llm/huggingface/datasets-basics">数据集基础</a> → <a href="/Front2Full/manual/llm/huggingface/finetune-lora">LoRA 微调</a></td></tr></tbody></table><p>国内读者建议无论如何先看一眼<a href="/Front2Full/manual/llm/huggingface/china-access">国内访问</a>——它能省掉后面大量“下载卡住”的困惑。</p><p>准备好了，从<a href="/Front2Full/manual/llm/huggingface/what-is-huggingface">HuggingFace 到底是什么</a>开始。</p>',29)])])}const p=e(o,[["render",g]]);export{h as __pageData,p as default};
